!function(){"use strict";app.factory("facturaCompraService",(function($injector){let url="FacturaCompra/",mS=$injector.get("mainService"),service={getAll:function(query){return mS.getData("get",url+"?json="+JSON.stringify(query),null,!0).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let results;return(JSON.parse(response.payload)[0]||[]).map(item=>({abono:item.abono,codDoc:item.codDoc,codEstab:item.codEstab,correo:item.correo,direccion:item.direccion,estadoFinanciero:item.estadoFinanciero,fechaEmision:item.fechaEmision,fechaVencimiento:item.fechaVencimiento,idFacturaCompra:item.idFacturaCompra,idProveedor:item.idProveedor,item:item.idTiempoCredito,idTipoDocumento:item.idTipoDocumento,nroDocumento:item.nroDocumento,nroIdentificacion:item.nroIdentificacion,nroRetencion:item.nroRetencion,proveedor:item.proveedor,retencion:item.retencion,saldo:item.saldo,total:item.total,usuario:item.usuario}))}})},save:function(data){return mS.getData("post",url+"Insert",data,!0).then(response=>response)},update:function(id,data){return mS.getData("put",url+"Update/"+id,data,!0).then(response=>response)},delete:function(id){return mS.getData("delete",url+id,null,!0).then(response=>response)},findByProveedor:function(idProveedor){return mS.getData("get",url+"FindByProveedor/"+idProveedor,null,!0).then(response=>{if("0"===response.code)return response;if("1"===response.code){let facturas;return{code:"1",payload:JSON.parse(response.payload)||[]}}})},findById:function(id){},queryMapper:function({data:data,details:details,proveedor:proveedor,datosAdicionalesArticulo:datosAdicionalesArticulo}){data.idProveedor=proveedor.idProveedor;let query={factura:data,detalle:service.detalleMapTo(details),datosAdiciones:JSON.stringify(datosAdicionalesArticulo.map(obj=>({idInfoAdicional:obj.idInfoAdicional||0,idArticulo:obj.idArticulo,idEtiqueta:obj.idEtiqueta,jsonAdicional:obj.adicionales})))};return JSON.stringify(query)},detalleMapTo:function(detalles){let index=1;return detalles.map(item=>{let data;return{ordeIndex:index++,idFacturaCompraDetalle:item.idFacturaCompraDetalle||0,idBodega:item.idBodega,idArticulo:item.idArticulo,idMedida:item.idMedida,idTipoIva:item.idTipoIva,descripcion:item.descripcion,cantidad:item.cantidad,precioUnitario:item.precioUnitario,precioCostoNeto:item.precioCostoNeto,porcentajeDescuento:item.porcentajeDescuento,valorDescuento:item.valorDescuento,ice:item.ice,iva:item.iva,codigoPorcentaje:item.codigoPorcentaje,tarifa:item.tarifa,nota:item.nota||null,total:item.total}})}};return service}))}(window.angular);